update_rule.pseudocode:
mandate_active = (current_day >= mandate_start_day) and (current_day <= mandate_end_day)
for each location L:
  if mandate_active and ((L.type=='work' and mandate_work) or (L.type=='retail' and mandate_retail) or (L.type=='transit' and mandate_transit) or (L.type=='home' and mandate_home)):
    L.mandate_status = 1
  else:
    L.mandate_status = 0
  L.enforcement_level = enforcement_level + signage_effect * L.signage_or_prompts
for each person i:
  expected_penalty = enforcement_detection_prob * (denial_of_entry_penalty + fine_penalty)
  Person[i].policy_pressure = policy_influence_weight * (communication_intensity + expected_penalty) * mandate_active

for each person i and each context c in daily_activity_schedule where c==1:
  U_i_c = Person[i].peer_signal + Person[i].media_signal + Person[i].policy_pressure + (Person[i].risk_perception * Person[i].perceived_mask_efficacy) + context_modifier_c - Person[i].perceived_discomfort_cost
  if Person[i].mask_inventory <= 0:
    U_i_c -= 5.0  # hard constraint penalty if no mask available
  p_i_c = sigmoid(U_i_c / max(1e-6, decision_noise_temperature))
  wear_i_c ~ Bernoulli(p_i_c)
  if wear_i_c == 1:
    Person[i].current_mask_use[c] = 1
    Person[i].mask_inventory = max(0, Person[i].mask_inventory - mask_use_rate_per_day)
  else:
    Person[i].current_mask_use[c] = 0
# Habit persistence (inertia)
for each person i:
  Person[i].mask_attitude = (1 - habit_persistence)*Person[i].mask_attitude + habit_persistence*mean_over_c(Person[i].current_mask_use[c])
